const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const arctic = ee.Geometry.Rectangle([-180, 63, 180, 90], 'EPSG:4326', false);
  const startDate2011 = '2011-04-01';
  const endDate2011 = '2011-04-30';
  const startDate2014 = '2014-04-01';
  const endDate2014 = '2014-04-30';
  const collectionName = 'TOMS/OMI/AURA/L3_O3_T';
  const band = 'O3';
  const scale = 3000;

  // 2. Data Acquisition & Check
  const collection2011 = ee.ImageCollection(collectionName)
    .filterBounds(arctic)
    .filterDate(startDate2011, endDate2011)
    .select(band);

  const collection2014 = ee.ImageCollection(collectionName)
    .filterBounds(arctic)
    .filterDate(startDate2014, endDate2014)
    .select(band);

  const size2011 = collection2011.size().getInfo();
  const size2014 = collection2014.size().getInfo();

  if (size2011 === 0 || size2014 === 0) {
    console.log(`Image count 2011: ${size2011}`);
    console.log(`Image count 2014: ${size2014}`);
    console.log("Empty collection for one or both periods.");
    console.log("C1");
    return;
  }
  console.log(`Image count 2011: ${size2011}`);
  console.log(`Image count 2014: ${size2014}`);

  // 3. Processing
  const mean2011 = collection2011.mean().clip(arctic);
  const mean2014 = collection2014.mean().clip(arctic);

  const statsReducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats2011 = mean2011.reduceRegion({
    reducer: statsReducer,
    geometry: arctic,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const stats2014 = mean2014.reduceRegion({
    reducer: statsReducer,
    geometry: arctic,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  // 4. Calculation
  const avgOzone2011 = stats2011[`${band}_mean`];
  const count2011 = stats2011[`${band}_count`];
  const avgOzone2014 = stats2014[`${band}_mean`];
  const count2014 = stats2014[`${band}_count`];

  // 5. Validation & Final Answer
  if (count2011 === 0 || count2014 === 0) {
    console.log(`Valid pixels 2011: ${count2011}`);
    console.log(`Valid pixels 2014: ${count2014}`);
    console.log("No valid pixels found after processing.");
    console.log("C2");
    return;
  }
  console.log(`Valid pixels 2011: ${count2011}`);
  console.log(`Valid pixels 2014: ${count2014}`);

  if (avgOzone2011 === null || avgOzone2014 === null) {
    console.log("Calculation resulted in null value.");
    console.log("C3");
    return;
  }

  console.log(`Avg Ozone 2011 (Dobson Units): ${avgOzone2011.toFixed(2)}`);
  console.log(`Avg Ozone 2014 (Dobson Units): ${avgOzone2014.toFixed(2)}`);

  if (avgOzone2014 > avgOzone2011) {
    console.log("Ozone concentration increased in April 2014 compared to April 2011.");
    console.log("A");
  } else {
    console.log("Ozone concentration did not increase in April 2014 compared to April 2011.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
